/* Parallelism by HTML5 UP | html5up.net | @ajlkn | CC BY 3.0.
 * Adapted for ImmichPager; composition, typography and accessibility modified. */
.ip-hero { max-width:none; padding:32px; gap:24px; }
.ip-hero .ip-header { background:#b72f48; color:#ffffff; --pager-muted:#ffffff; padding:32px; }
.ip-hero .ip-banner { height:220px; }
.ip-title { font-weight:var(--pager-title-font-weight); letter-spacing:-.035em; }
.ip-hero .ip-navigation { padding:12px 0; border-color:#ffffff33; }
.ip-block { max-width:none; padding-inline:24px; }
.ip-block .block-heading { font-weight:400; }
.ip-photo::after { display:none; }
@media(max-width:760px) { .ip-hero { padding:20px; } .ip-hero .ip-header { padding:24px; } .ip-block { padding-inline:20px; } }

.ip-description { opacity:1; }

.ip-albums:not(.tiles) .ip-album-info p { opacity:1; color:var(--pager-muted); }
.ip-albums.tiles .ip-album-info p { opacity:1; color:#ffffff; }
